fn numbers() -> &'static Regex {
    static PATTERN: OnceLock<Regex> = OnceLock::new();
    PATTERN.get_or_init(|| Regex::new(r"-?\d+(?:\.\d+)?").unwrap())
}

fn commands() -> &'static Regex {
    static PATTERN: OnceLock<Regex> = OnceLock::new();
    PATTERN.get_or_init(|| Regex::new(r"([MLHVQCZ])([^MLHVQCZ]*)").unwrap())
}

pub fn glyph(character: char) -> Option<&'static str> {
    GLYPHS
        .iter()
        .find(|(key, _)| *key == character)
        .map(|(_, path)| *path)
}

pub fn number(value: f64) -> String {
    let text = format!("{value:.2}");
    let text = match text.strip_suffix('0') {
        Some(shorter) => shorter.to_string(),
        None => text,
    };
    if text == "-0.0" {
        "0.0".to_string()
    } else {
        text
    }
}

pub fn shifted(path: &str, dx: f64) -> String {
    let mut parts = String::new();
    for capture in commands().captures_iter(path) {
        let command = capture.get(1).map_or("", |value| value.as_str());
        let arguments = capture.get(2).map_or("", |value| value.as_str());
        let values: Vec<f64> = numbers()
            .find_iter(arguments)
            .filter_map(|value| value.as_str().parse::<f64>().ok())
            .enumerate()
            .map(|(index, value)| match command {
                "H" => value + dx,
                "M" | "L" | "Q" | "C" if index % 2 == 0 => value + dx,
                _ => value,
            })
            .collect();
        parts.push_str(command);
        parts.push_str(
            &values
                .iter()
                .map(|value| number(*value))
                .collect::<Vec<_>>()
                .join(" "),
        );
    }
    parts
}

pub fn subtitle_text(name: &str) -> String {
    format!("{name} EXTENSION")
        .to_uppercase()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

pub fn check_subtitle(text: &str) -> AppResult<()> {
    let mut unsupported: Vec<char> = text
        .chars()
        .filter(|character| glyph(*character).is_none())
        .collect();
    unsupported.sort_unstable();
    unsupported.dedup();
    if !unsupported.is_empty() {
        let listed = unsupported
            .iter()
            .map(|character| format!("'{character}'"))
            .collect::<Vec<_>>()
            .join(", ");
        return Err(AppError::invalid(format!(
            "unsupported characters in the subtitle: {listed}; the outlined alphabet covers A-Z, 0-9, space and - . & + /"
        )));
    }
    if text.trim().is_empty() {
        return Err(AppError::invalid("the subtitle is empty"));
    }
    if text.chars().count() > MAX_SUBTITLE {
        return Err(AppError::invalid(format!(
            "the subtitle '{text}' is {} characters; at most {MAX_SUBTITLE} fit under the blade",
            text.chars().count()
        )));
    }
    Ok(())
}

pub fn subtitle_path(text: &str) -> AppResult<String> {
    check_subtitle(text)?;
    Ok(text
        .chars()
        .enumerate()
        .map(|(index, character)| shifted(glyph(character).unwrap_or(""), ADVANCE * index as f64))
        .filter(|outline| !outline.is_empty())
        .collect::<Vec<_>>()
        .join(" "))
}

pub fn subtitle_x(text: &str) -> f64 {
    let value = SUBTITLE_RIGHT - ADVANCE * SUBTITLE_SCALE * text.chars().count() as f64;
    (value * 100.0).round() / 100.0
}

pub fn escape(value: &str) -> String {
    value
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
}

pub fn banner_svg(name: &str, text: Option<&str>) -> AppResult<String> {
    let owned;
    let subtitle = match text {
        Some(value) => value,
        None => {
            owned = subtitle_text(name);
            &owned
        }
    };
    let label = escape(&format!(
        "FileBlade {} extension",
        name.trim().to_lowercase()
    ));
    let outline = subtitle_path(subtitle)?;
    Ok(format!(
        "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 {WIDTH} {BANNER_HEIGHT}\" width=\"{WIDTH}\" height=\"{BANNER_HEIGHT}\" role=\"img\" aria-label=\"{label}\">\n{body}<path transform=\"translate({x:.2},{y:.2}) scale({SUBTITLE_SCALE})\" d=\"{outline}\" fill=\"{AMBER}\"/>\n</svg>\n",
        body = LOGO_BODY.replace(LOGO_MASK, BANNER_MASK),
        x = subtitle_x(subtitle),
        y = SUBTITLE_Y,
    ))
}

pub fn host_logo_svg() -> String {
    format!(
        "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 {WIDTH} {LOGO_HEIGHT}\" width=\"{WIDTH}\" height=\"{LOGO_HEIGHT}\" role=\"img\" aria-label=\"FileBlade\">\n{LOGO_BODY}</svg>\n"
    )
}

pub fn rasterize(svg: &str, target: &Path, width: u32) -> AppResult<()> {
    let tool = which("rsvg-convert").ok_or_else(|| {
        AppError::command("rsvg-convert is not installed; install librsvg or keep the SVG only")
    })?;
    let output = CommandSpec::new(tool)
        .args(["--width".to_string(), width.to_string()])
        .args(["--keep-aspect-ratio", "--format", "png", "--output"])
        .args([target])
        .stdin(svg.as_bytes().to_vec())
        .timeout(RASTERIZE_TIMEOUT)
        .limits(RASTERIZE_STDOUT_LIMIT, RASTERIZE_STDERR_LIMIT)
        .run()?;
    if !output.status.success() {
        return Err(AppError::command(format!(
            "rsvg-convert failed: {}",
            String::from_utf8_lossy(&output.stderr).trim()
        )));
    }
    Ok(())
}

pub fn manifest_name(manifest: &Path) -> AppResult<String> {
    let bytes = std::fs::read(manifest).map_err(|error| {
        AppError::invalid(format!("cannot read {}: {error}", manifest.display()))
    })?;
    if bytes.len() as u64 > MANIFEST_LIMIT {
        return Err(AppError::invalid(format!(
            "cannot read {}: the manifest is larger than {MANIFEST_LIMIT} bytes",
            manifest.display()
        )));
    }
    let document: serde_json::Value = serde_json::from_slice(&bytes).map_err(|error| {
        AppError::invalid(format!("cannot read {}: {error}", manifest.display()))
    })?;
    let name = document
        .get("name")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default()
        .trim()
        .to_string();
    if name.is_empty() {
        return Err(AppError::invalid(format!(
            "{} has no name; pass --name",
            manifest.display()
        )));
    }
    Ok(name.strip_prefix(NAME_PREFIX).unwrap_or(&name).to_string())
}
